<?php require_once "auth.php";require_once "../config/db.php";if(isset($_POST['status'])){$id=(int)$_POST['id'];$st=$_POST['status'];$s=$conn->prepare("UPDATE orders SET status=? WHERE order_id=?");$s->bind_param("si",$st,$id);$s->execute();}$r=$conn->query("SELECT o.*,u.first_name,u.last_name FROM orders o JOIN users u ON u.user_id=o.user_id ORDER BY o.order_id DESC");?>
